skin=""".hb{position:sticky;top:0;z-index:30;background:#EAF0F8;border-bottom:1px solid #9AA9C2}.hb-t{display:flex;align-items:center;gap:4px;padding:0 10px;background:#1F3A6B;color:#fff;min-height:34px}.hb-logo{font:700 15px var(--font);padding-right:14px;letter-spacing:.02em}.hb-m{display:flex}.mn{position:relative}.mn summary{list-style:none;cursor:pointer;padding:7px 12px;font-size:14px;color:#fff;min-height:34px}.mn summary::-webkit-details-marker{display:none}.mn[open] summary,.mn summary:hover{background:#34589B}.mnb{position:absolute;left:0;top:100%;min-width:230px;background:#fff;color:var(--text);border:1px solid #9AA9C2;box-shadow:0 8px 20px rgba(0,0,0,.25);padding:4px 0;z-index:40}.mnb a,.mnb button{display:block;width:100%;text-align:left;background:none;border:0;padding:8px 16px;font-size:14px;color:var(--text);text-decoration:none;min-height:36px}.mnb a:hover,.mnb button:hover{background:var(--sel)}.hb .sp{flex:1}.hb .cmd{flex:0 1 260px;min-height:28px;padding:2px 12px;font-size:13px;border-radius:4px;background:#fff}.hb-tool{display:flex;gap:2px;padding:4px 10px;overflow-x:auto}.hb-tool .grp,.hb-tool .grp-b{display:contents}.hb-tool .grp-h{display:none}.hb-tool a{display:flex;flex-direction:column;align-items:center;gap:1px;padding:4px 14px;min-height:52px;min-width:76px;border:1px solid transparent;border-radius:4px;color:#1F3A6B;text-decoration:none;font-size:12px;white-space:nowrap;position:relative}.hb-tool a:hover{background:#fff;border-color:#9AA9C2}.hb-tool a[aria-current]{background:#fff;border-color:#2540C9;font-weight:700;box-shadow:inset 0 -3px 0 #2540C9}.hb-tool a svg{width:22px;height:22px}.hb-tool .nb{position:absolute;top:0;right:6px;margin:0}.hb-s{position:sticky;bottom:0;display:flex;gap:18px;padding:3px 12px;background:#DCE4F1;border-top:1px solid #9AA9C2;font-size:12px;color:var(--muted)}.hb-s .sp{flex:1}.hb~.main{min-height:calc(100vh - 190px)}.hb~.main .top{display:none}.main{padding:10px 12px 40px;max-width:none}.pg{max-width:none}.rc{border:1px solid #9AA9C2;background:#fff}.rc-hd{display:flex;gap:14px;padding:8px 12px;background:#F3F6FB;border-bottom:1px solid #9AA9C2;align-items:flex-start}.rc-av{flex:none;width:56px;height:56px;border:1px solid #9AA9C2;background:#DCE4F1;color:#1F3A6B;font:700 18px var(--font);display:grid;place-items:center}.rc-g{flex:1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px 18px}.rc-f{display:flex;gap:6px;min-width:0}.rc-f span{color:var(--muted);white-space:nowrap}.rc-f span::after{content:":"}.rc-f b{font-weight:600;overflow-wrap:anywhere}.rc-f i{font-weight:400;color:var(--muted)}.rc-nm{font-size:16px}.rc-owe{color:#B91C1C}.rc-act{display:flex;gap:6px}.rc-mid{display:grid;grid-template-columns:minmax(280px,1fr) minmax(0,2fr);gap:10px;padding:8px 12px;border-bottom:1px solid #9AA9C2}.rc-pn h3{font-size:13px;margin:0 0 4px}.rc-pn .tbl{border:1px solid #9AA9C2}.rc-al .tbl{border-color:#B91C1C}.rc-red{color:#B91C1C}.rc-gr{color:#166534}.rc-body{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:48vh}.rc-tree{background:#F3F6FB;border-right:1px solid #9AA9C2;padding:6px 0}.rc-tree ul{list-style:none;margin:0;padding:0}.rc-tree a{display:flex;align-items:center;gap:8px;padding:6px 12px;color:var(--text);text-decoration:none;font-weight:600;border-left:3px solid transparent}.rc-tree a svg{width:18px;height:18px;color:#1F3A6B;flex:none}.rc-tree a:hover{background:#fff}.rc-tree a[aria-current]{background:#fff;border-left-color:#2540C9;color:#1B31A3}.rc-tree em{margin-left:auto;font-style:normal;font-size:11px;background:#DCE4F1;border-radius:9px;padding:0 6px}.rc-main{padding:8px 12px;min-width:0;overflow-x:auto}.rc-h{font-size:15px;margin:0 0 6px}.rc-bar{display:flex;gap:6px;align-items:center;margin-bottom:6px}.rc-main .grid2{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}@media (max-width:1099px){.rc-g{grid-template-columns:repeat(2,minmax(0,1fr))}.rc-mid{grid-template-columns:1fr}}@media (max-width:899px){.rc-hd{flex-wrap:wrap}.rc-body{grid-template-columns:1fr}.rc-tree{border-right:0;border-bottom:1px solid #9AA9C2}.rc-tree ul{display:flex;overflow-x:auto}.rc-tree a{white-space:nowrap;border-left:0;border-bottom:3px solid transparent}.rc-tree a[aria-current]{border-bottom-color:#2540C9}}@media (min-width:900px){:root{--r:3px;--rc:3px}body{font-size:13px;line-height:1.35}.hb~.main .btn{min-height:28px;padding:2px 10px;font-size:13px;font-weight:600}.hb~.main .fld input:not([type=checkbox]),.hb~.main .fld select,.hb~.main .fld textarea{min-height:30px;padding:3px 8px;font-size:13px}.hb~.main .fl,.hb~.main .seg button,.hb~.main .tabs a{min-height:28px;padding:2px 10px;font-size:13px}.hb~.main .tbl{font-size:13px}.hb~.main .tbl th{background:#DCE4F1;padding:4px 8px;text-align:left;border-bottom:1px solid #9AA9C2}.hb~.main .tbl td{padding:3px 8px;border-bottom:1px solid var(--line)}.hb~.main .tbl tbody tr:nth-child(even){background:#F6F8FC}.hb~.main .tbl tbody tr:hover{background:var(--sel)}.hb~.main .vh h1{font-size:17px}.hb~.main .vh{margin:0 0 8px}.hb~.main .chip{font-size:11px;line-height:16px;padding:0 6px;border-radius:2px}.hb~.main .dk-hi{font-size:17px}.hb~.main .dk-kp{grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin-bottom:8px}.hb~.main .dk-kp a{padding:5px 10px;flex-direction:row;align-items:baseline;gap:8px}.hb~.main .dk-g{gap:8px}.hb~.main .book li{padding-block:3px}.hb~.main .calbox{height:calc(100vh - 250px)}}@media (max-width:899px){.hb-m{display:none}.hb-t .cmd{margin-left:auto}.hb-s{display:none}}.navb .kbd{display:none}.book .t,.navb .foot .kbd{font-family:var(--mono)}.navb .foot .kbd{display:inline;background:transparent;color:var(--nav-fg);border-color:#4A5470}"""
